import {CollectionFilter} from './CollectionFilter';
import React,{useEffect,useRef,useState} from 'react';
import * as Dialog from '@radix-ui/react-dialog';
import {Check,FileText,Pencil,Plus,Search,X,Clock,CalendarDays,MessageSquare} from 'lucide-react';
import {WorkspaceFilters,WorkspaceSelect} from './workspace/WorkspaceUI';
import {DEFAULT_WORKFLOW,workflowOptionsFor,briefFieldsFor,workflowFor} from '../lib/workflows';
import {PIPELINE_STAGES as stages,ACTIVE_PIPELINE_STAGES as activeStages,stageLabelsFor,isOpenEnquiry,nextStepFor,attentionFor,sortByAttention} from '../lib/pipeline.mjs';
import {DealOverview,DealQuote,DealFollowUps,SignalChips,Chip,whyFor,primaryFor} from './PipelineDeal';
import {StageStrip,DatesView,InsightsView,AutomationsView,SummaryTiles,TodaySide} from './PipelineViews';
import {QuietHelper} from './QuietHelper';
import {OpenedLine} from './OpenedNote';
import '../folio-crm-growth.css';

const money=(minor,currency='GBP')=>new Intl.NumberFormat('en-GB',{style:'currency',currency,maximumFractionDigits:0}).format((minor||0)/100);
const localISODate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const shortDate=value=>value?new Date(value.length===10?value+'T12:00:00':value).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'No date';
const initials=name=>(name||'').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();
const defaultDraft=o=>({title:o?.title||'',description:o?.description||'',stage:o?.stage||'Discovery',amount:o?(o.amountMinor/100).toFixed(2):'',currency:o?.currency||'GBP',probability:o?.probability??20,expectedClose:o?.expectedClose||'',lostReason:o?.lostReason||'',source:o?.source||''});
const readError=e=>e?.message||'Something went wrong. Please try again.';

export function PipelineCRM({studio,request,run,busy,openClient,openProject,openTask,onProjectCreated,onReviewChange,opportunityId,initialClientId,onSelectOpportunity}){
 const [opportunities,setOpportunities]=useState([]),[clients,setClients]=useState([]),[tasks,setTasks]=useState([]),[assignments,setAssignments]=useState({});
 const [detail,setDetail]=useState(null),[detailError,setDetailError]=useState(''),[selected,setSelected]=useState(opportunityId),[draft,setDraft]=useState(defaultDraft());
 const [layout,setLayout]=useState('Today'),[inspectorOpen,setInspectorOpen]=useState(Boolean(opportunityId)),[query,setQuery]=useState(''),[stageFilter,setStageFilter]=useState('Open'),[page,setPage]=useState(1),[pageSize,setPageSize]=useState(25);
 const [creating,setCreating]=useState(false),[creatingProject,setCreatingProject]=useState(false),[loading,setLoading]=useState(true),[error,setError]=useState(''),[actionError,setActionError]=useState('');
 const [editing,setEditing]=useState(false),[logging,setLogging]=useState(false),[activityKind,setActivityKind]=useState('Call'),[taskTitle,setTaskTitle]=useState(''),[taskDate,setTaskDate]=useState(''),[undo,setUndo]=useState(null),[message,setMessage]=useState(''),[closingEnquiry,setClosingEnquiry]=useState(null);
 const [pipeline,setPipeline]=useState(null),[boardStage,setBoardStage]=useState('Discovery'),[drawerTab,setDrawerTab]=useState('overview');
 const boardRef=useRef(null),openerRef=useRef(null),taskInput=useRef(null),headingRef=useRef(null),listRef=useRef(null),reloadVersion=useRef(0),studioRef=useRef(studio.id);
 studioRef.current=studio.id;
 const q='?studio='+studio.id,today=localISODate(),labels=stageLabelsFor(studio);
 async function reload(){const version=++reloadVersion.current,studioId=studio.id;try{const [o,c,t,a]=await Promise.all([request('/api/opportunities'+q),request('/api/clients'+q),request('/api/crm/tasks'+q),request('/api/task-workspace'+q)]);if(version!==reloadVersion.current||studioRef.current!==studioId)return;setOpportunities(o.opportunities);setClients(c.clients);setTasks(t.tasks);setAssignments(a.assignments||{});setError('');request('/api/pipeline'+q).then(d=>{if(version===reloadVersion.current&&studioRef.current===studioId&&d&&d.signals)setPipeline(d);}).catch(()=>{});}catch(e){if(version===reloadVersion.current&&studioRef.current===studioId)setError(readError(e));}finally{if(version===reloadVersion.current&&studioRef.current===studioId)setLoading(false);}}
 useEffect(()=>{setLoading(true);reload();},[studio.id]);
 useEffect(()=>{if(initialClientId&&!opportunityId)setCreating(true);},[studio.id]);
 useEffect(()=>{if(opportunityId){setSelected(opportunityId);setInspectorOpen(true);}},[opportunityId]);
 useEffect(()=>{if(!inspectorOpen)return;setDetail(null);setDetailError('');if(!selected)return;let active=true;request('/api/opportunities/'+selected+q).then(d=>{if(active){setDetail(d.opportunity);setDraft(defaultDraft(d.opportunity));}}).catch(e=>{if(active)setDetailError(readError(e));});return()=>{active=false;};},[selected,studio.id,inspectorOpen]);
 // Keep the current stage in view on a narrow drawer.
 useEffect(()=>{const path=document.querySelector('.pl-path'),now=path?.querySelector('.is-now');if(path&&now)path.scrollLeft=now.offsetLeft-path.offsetLeft-(path.clientWidth-now.offsetWidth)/2;},[detail?.id,detail?.stage,drawerTab]);
 const signals=pipeline?.signals||{},flagsOf=o=>signals[o.id]?.flags||[],urgent=o=>flagsOf(o).some(f=>f.rank<=3);
 const needsYou=o=>isOpenEnquiry(o)&&(!!attentionFor(o,tasks,today)||urgent(o));
 const scoped=opportunities.filter(o=>!initialClientId||o.clientId===initialClientId),open=scoped.filter(isOpenEnquiry),attention=open.filter(needsYou);
 const visible=scoped.filter(o=>(stageFilter==='All'||stageFilter==='Open'&&isOpenEnquiry(o)||stageFilter==='Closed'&&!isOpenEnquiry(o)||stageFilter===o.stage)&&`${o.title} ${o.clientName} ${o.source}`.toLowerCase().includes(query.toLowerCase()));
 const listed=layout==='Today'?sortByAttention(visible.filter(needsYou),tasks,today):visible;
 const todayGroup=o=>{const issue=attentionFor(o,tasks,today),flags=flagsOf(o);if(issue?.kind==='review')return 0;if(flags.some(f=>f.rank<=2))return 1;if(flags.some(f=>f.kind==='silent'))return 2;if(['overdue','today'].includes(issue?.kind))return 3;return 4;};
 const stageChoices=stageFilter==='Closed'?stages.slice(4):stageFilter==='Open'?activeStages:stageFilter==='All'?stages:[stageFilter];
 const groups=layout==='Today'?['New enquiries to review','Needs a decision from you','Waiting on the client','Follow-ups to make','Plan the next step'].map((label,index)=>[label,listed.filter(o=>todayGroup(o)===index)]).filter(([,items])=>items.length):stageChoices.map(s=>[labels[s],listed.filter(o=>o.stage===s)]).filter(([,items])=>items.length);
 const totalRows=groups.reduce((count,[,items])=>count+items.length,0),pageCount=Math.max(1,Math.ceil(totalRows/pageSize)),currentPage=Math.min(page,pageCount),start=(currentPage-1)*pageSize;
 const pageIds=new Set(groups.flatMap(([,items])=>items).slice(start,start+pageSize).map(o=>o.id));
 const pageGroups=groups.map(([label,items])=>[label,items.filter(o=>pageIds.has(o.id))]).filter(([,items])=>items.length);
 useEffect(()=>setPage(1),[query,stageFilter,layout,initialClientId,studio.id,pageSize]);
 useEffect(()=>{if(page>pageCount)setPage(pageCount);},[page,pageCount]);
 function changePage(value){setPage(value);listRef.current?.focus();listRef.current?.scrollIntoView({block:'start'});}
 const stageOptions=stages.map(value=>({value,label:labels[value]}));
 const taskOwner=t=>assignments['crm:'+t?.id]||studio.name;
 const currentBoardStage=stageChoices.includes(boardStage)?boardStage:stageChoices[0];
 function focusStage(stage){setBoardStage(stage);const column=boardRef.current?.querySelector(`[data-stage="${stage}"]`);if(column&&boardRef.current)boardRef.current.scrollTo?.({left:column.offsetLeft-boardRef.current.offsetLeft,behavior:'smooth'});}
 async function saveAutomations(settings){const result=await act('/api/pipeline'+q,'POST',{action:'save',settings});if(result){setPipeline(result);await reload();return true;}return false;}
 async function dealChanged(){await reload();if(selected){try{const d=await request('/api/opportunities/'+selected+q);setDetail(d.opportunity);setDraft(defaultDraft(d.opportunity));}catch(e){setActionError(readError(e));}}}
 async function act(path,method,body){setActionError('');return run(async()=>{try{return await request(path,method,body);}catch(e){setActionError(readError(e));return null;}});}
 function select(id,opener,tab='overview'){if(opener)openerRef.current=opener;setDrawerTab(tab);setDetail(null);setDetailError('');setActionError('');setEditing(false);setLogging(false);setTaskTitle('');setTaskDate('');setMessage('');setUndo(null);setSelected(id);setInspectorOpen(true);onSelectOpportunity?.(id);}
 function stageChanged(previous,result){setUndo({id:previous.id,from:previous.stage,to:result.stage,probability:previous.probability,lostReason:previous.lostReason,revision:result.revision});setMessage(`Moved to ${labels[result.stage]}.`);}
 async function save(e){e.preventDefault();if(!detail)return;const amount=Number(draft.amount||0),probability=Number(draft.probability);if(!Number.isFinite(amount)||amount<0){setActionError('Enter a valid enquiry value.');return;}const previous=detail,result=await act('/api/opportunities/'+detail.id+q,'PATCH',{...draft,amountMinor:Math.round(amount*100),probability,revision:detail.revision});if(result){if(previous.stage!==result.opportunity.stage)stageChanged(previous,result.opportunity);else {setUndo(null);setMessage('Enquiry details saved.');}setDetail(result.opportunity);setDraft(defaultDraft(result.opportunity));setEditing(false);await reload();}}
 async function move(opportunity,stage){if(busy||stage===opportunity.stage)return;if(stage==='Lost'){setClosingEnquiry(opportunity);setActionError('');return;}
 const result=await act('/api/opportunities/'+opportunity.id+q,'PATCH',{revision:opportunity.revision,stage});if(result){stageChanged(opportunity,result.opportunity);if(selected===opportunity.id){setDetail(result.opportunity);setDraft(defaultDraft(result.opportunity));}await reload();}}
 async function undoMove(){if(!undo)return;const result=await act('/api/opportunities/'+undo.id+q,'PATCH',{revision:undo.revision,stage:undo.from,probability:undo.probability,lostReason:undo.lostReason});if(result){if(selected===undo.id){setDetail(result.opportunity);setDraft(defaultDraft(result.opportunity));}setUndo(null);setMessage('Stage change undone.');await reload();}}
 async function create(e){e.preventDefault();const raw=Object.fromEntries(new FormData(e.currentTarget)),amount=Number(raw.amount||0);if(!Number.isFinite(amount)||amount<0){setActionError('Enter a valid enquiry value.');return;}const result=await act('/api/opportunities'+q,'POST',{...raw,amountMinor:Math.round(amount*100),probability:20});if(result){setCreating(false);setStageFilter('Open');setLayout('All enquiries');setQuery('');select(result.opportunity.id);await reload();}}
 async function createProject(e){e.preventDefault();if(!detail)return;const raw=Object.fromEntries(new FormData(e.currentTarget));const result=await act('/api/opportunities/'+detail.id+'/project'+q,'POST',{...raw,revision:detail.revision});if(result){setCreatingProject(false);setDetail(result.opportunity);await reload();onProjectCreated(result.project);}}
 async function reviewEnquiry(){if(!detail)return;const result=await act('/api/opportunities/'+detail.id+'/review'+q,'POST',{revision:detail.revision,reviewed:!detail.reviewedAt});if(result){setDetail(result.opportunity);setDraft(defaultDraft(result.opportunity));onReviewChange?.(result.opportunity.projectId,result.opportunity.reviewedAt);setMessage(result.opportunity.reviewedAt?'Enquiry reviewed. Plan the next step below.':'Enquiry marked for review.');setUndo(null);await reload();}}
 async function beginPlanning(){if(!detail?.projectId)return;const result=await act('/api/opportunities/'+detail.id+'/planning'+q,'POST',{revision:detail.revision,projectUpdatedAt:detail.projectUpdatedAt});if(result){await reload();onProjectCreated(result.project);}}
 async function addActivity(e){e.preventDefault();if(!detail)return;const form=e.currentTarget,raw=Object.fromEntries(new FormData(form)),result=await act('/api/opportunities/'+detail.id+'/activities'+q,'POST',{...raw,kind:activityKind});if(result){form.reset();setLogging(false);setDetail(prev=>({...prev,activities:result.activities}));await reload();}}
 async function addTask(e){e.preventDefault();if(!detail)return;const result=await act('/api/crm/tasks'+q,'POST',{title:taskTitle,dueDate:taskDate,priority:'Normal',clientId:detail.clientId,opportunityId:detail.id});if(result){setTaskTitle('');setTaskDate('');setDetail(prev=>({...prev,tasks:[...(prev.tasks||[]),result.task]}));setMessage('Next step added.');await reload();}}
 async function toggleTask(task){const result=await act('/api/crm/tasks/'+task.id+q,'PATCH',{completed:!task.completed});if(result){setDetail(prev=>({...prev,tasks:prev.tasks.map(t=>t.id===task.id?result.task:t)}));await reload();}}
 function suggestTask(title){setTaskTitle(title);taskInput.current?.focus();}
 function queueItem(o){const issue=attentionFor(o,tasks,today),s=signals[o.id],primary=primaryFor(o,s,issue);
 return <article className="pl-qitem" key={o.id}><span className="pl-avatar" aria-hidden="true">{initials(o.clientName)}</span><div className="pl-qbody"><button type="button" className="pl-qname" aria-label={'View '+o.title} aria-haspopup="dialog" onClick={e=>select(o.id,e.currentTarget)}><strong>{o.clientName}</strong><small>{o.title}</small>{o.projectStatus&&o.projectStatus!=='Enquiry'&&<em className="pl-stage">Project in {o.projectStatus.toLowerCase()}</em>}</button><SignalChips signal={s}/><OpenedLine opened={s?.opened}/><p className="pl-why">{whyFor(o,s,issue)}</p></div>
 <div className="pl-acts"><button type="button" className="pl-btn is-small" onClick={e=>primary.billing?openProject({id:o.projectId},'Billing'):select(o.id,e.currentTarget,primary.tab)}>{primary.label}</button>{primary.label!=='Open'&&<button type="button" className="pl-btn is-small is-ghost" onClick={e=>select(o.id,e.currentTarget)}>Open</button>}</div></article>;}
 function card(o){const s=signals[o.id];return <button type="button" draggable={!busy} onDragStart={e=>e.dataTransfer.setData('text/plain',o.id)} key={o.id} className="pl-card" aria-label={'View '+o.title} aria-haspopup="dialog" onClick={e=>select(o.id,e.currentTarget)}><strong>{o.clientName}</strong><small>{o.title}</small>{o.projectStatus&&o.projectStatus!=='Enquiry'&&<em className="pl-stage">Project in {o.projectStatus.toLowerCase()}</em>}<SignalChips signal={s}/><OpenedLine opened={s?.opened}/><span className="pl-card-bottom"><span>{s?.eventDate?shortDate(s.eventDate):'No date yet'}</span><span>{o.amountMinor?money(o.amountMinor,o.currency):'Not estimated'}</span></span></button>;}
 const columnTotal=list=>Object.entries(list.reduce((r,o)=>{if(o.amountMinor)r[o.currency]=(r[o.currency]||0)+o.amountMinor;return r;},{})).map(([c,v])=>money(v,c)).join(' · ')||'No value yet';
 function row(o,board=false){const next=nextStepFor(o,tasks),issue=attentionFor(o,tasks,today);return <button type="button" draggable={!busy} onDragStart={e=>e.dataTransfer.setData('text/plain',o.id)} key={o.id} className={'pipeline-enquiry'+(board?' is-board-card':'')+(issue?.kind==='overdue'?' is-overdue':'')} aria-label={'View '+o.title} aria-haspopup="dialog" onClick={e=>select(o.id,e.currentTarget)}>
 <span className="pipeline-person"><span className="pipeline-avatar">{initials(o.clientName)}</span><span><strong>{o.clientName}</strong><small>{o.title}</small><small className="pipeline-source">{o.formName?'From '+o.formName:o.source||'Direct enquiry'}{o.projectStatus&&o.projectStatus!=='Enquiry'?` · Project in ${o.projectStatus.toLowerCase()}`:''}</small><SignalChips signal={signals[o.id]}/><OpenedLine opened={signals[o.id]?.opened}/></span></span>
 <span className="pipeline-next"><strong>{issue?.kind==='review'?'Review their request':next?.title||'Set a next step'}</strong><small>{next?`${next.dueDate?shortDate(next.dueDate):'Date needed'} · ${taskOwner(next)}`:'Keep this enquiry moving'}</small>{issue&&['overdue','today'].includes(issue.kind)&&<em className={'pipeline-attention '+issue.kind}>{issue.label}</em>}</span>
 <span className="pipeline-value"><strong>{o.amountMinor?money(o.amountMinor,o.currency):'Not estimated'}</strong><small>{labels[o.stage]}</small></span><span className="pipeline-view">View</span></button>;}
 return <section className="crm-screen pipeline-workspace">
 <header className="crm-page-heading workspace-page-heading"><div><h1 ref={headingRef} tabIndex={-1}>Pipeline</h1><p>Keep every enquiry moving towards a clear decision.</p></div><button className="crm-primary" onClick={()=>{setActionError('');setCreating(true);}}><Plus size={16}/>New enquiry</button></header>
 {error&&<p className="crm-alert" role="alert">{error}<button onClick={reload}>Try again</button></p>}
 {!inspectorOpen&&!creating&&!creatingProject&&actionError&&<p className="crm-alert" role="alert">{actionError}</p>}
 <SummaryTiles open={open} attention={attention.length} dates={pipeline?.dates} onAttention={()=>{setLayout('Today');setStageFilter('Open');setQuery('');}}/>
 <div className="pipeline-toolbar"><WorkspaceFilters label="Pipeline view" items={['Today','All enquiries','Board','Dates','Insights','Automations']} value={layout} onChange={value=>{setLayout(value);if(value==='Today')setStageFilter('Open');}}/>{['Today','All enquiries','Board'].includes(layout)&&<div className="pipeline-tools"><CollectionFilter label="Filter enquiries" value={query} onChange={setQuery} placeholder="Client or enquiry…"/>{layout!=='Insights'&&<WorkspaceSelect label="Enquiry stage" value={stageFilter} onValueChange={setStageFilter} options={[{value:'Open',label:'Open enquiries'},...(layout==='Today'?[]:[{value:'All',label:'All stages'},{value:'Closed',label:'Closed enquiries'}]),...stageOptions.filter(o=>layout!=='Today'||activeStages.includes(o.value))]}/>}</div>}</div>
 {loading?<p className="pipeline-empty" role="status">Opening your enquiries…</p>:layout==='Insights'?<InsightsView opportunities={scoped} labels={labels} insights={pipeline?.insights}/>:layout==='Dates'?<DatesView dates={pipeline?.dates||[]} capacity={pipeline?.settings?.dailyCapacity||1} onOpen={(id,el)=>select(id,el)}/>:layout==='Automations'?<AutomationsView settings={pipeline?.settings} busy={busy} onSave={saveAutomations}/>:layout==='Board'?<><StageStrip stages={stageChoices} labels={labels} items={visible} signals={signals} current={currentBoardStage} onChange={focusStage}/><div className="pipeline-board" ref={boardRef}>{stageChoices.map(stage=><section className={'pipeline-board-column'+(stage===currentBoardStage?' is-current':'')} data-stage={stage} key={stage} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();const o=scoped.find(o=>o.id===e.dataTransfer.getData('text/plain'));if(o)move(o,stage);}}><header><h2>{labels[stage]}</h2><span>{visible.filter(o=>o.stage===stage).length}</span></header><p className="pl-sum">{columnTotal(visible.filter(o=>o.stage===stage))}</p>{visible.filter(o=>o.stage===stage).map(o=><div className="pipeline-board-item" key={o.id}>{card(o)}<label className="pipeline-move"><span className="sr-only">Move {o.clientName} to</span><select value="" disabled={busy} onChange={e=>{if(e.target.value)move(o,e.target.value);}}><option value="">Move to…</option>{stages.filter(x=>x!==o.stage).map(x=><option key={x} value={x}>{labels[x]}</option>)}</select></label></div>)}{!visible.some(o=>o.stage===stage)&&<p>No enquiries here</p>}</section>)}</div></>:<div className="pipeline-list" ref={listRef} tabIndex={-1} aria-label="Enquiry results">{groups.length?<>{layout==='Today'?<div className="pl-today"><div className="pl-queue">{pageGroups.map(([label,items])=><section className="pl-qgroup" key={label}><header className="pl-qhead"><h2 className="pl-label">{label}</h2><span>{items.length}</span></header>{items.map(queueItem)}</section>)}</div><TodaySide handled={pipeline?.handled} replySpeed={pipeline?.replySpeed} labels={labels} onOpen={(id,el)=>select(id,el)}/></div>:<><div className="pipeline-columns" aria-hidden="true"><span>Client / enquiry</span><span>Next step / responsible</span><span>Value / stage</span><span/></div>{pageGroups.map(([label,items])=><section className="pipeline-group" key={label}><header><h2>{label}</h2><span>{items.length}</span></header>{items.map(o=>row(o))}</section>)}</>}<nav className="pipeline-pagination" aria-label="Enquiry pagination"><span className="pipeline-page-range" role="status">{start+1}–{Math.min(start+pageSize,totalRows)} of {totalRows} enquiries</span><div className="pipeline-page-controls"><WorkspaceSelect label="Enquiries per page" value={String(pageSize)} onValueChange={value=>setPageSize(Number(value))} options={[10,25,50].map(size=>({value:String(size),label:size+' rows'}))}/><button type="button" disabled={currentPage===1} onClick={()=>changePage(currentPage-1)}>Previous</button><span>Page {currentPage} of {pageCount}</span><button type="button" disabled={currentPage===pageCount} onClick={()=>changePage(currentPage+1)}>Next</button></div></nav></>:<div className="pipeline-empty"><Check size={24}/><h2>{query?'No matching enquiries':layout==='Needs attention'?'No enquiries need attention here':'No enquiries in this view'}</h2><p>{query?'Try another client name or enquiry.':layout==='Needs attention'?'Every open enquiry is reviewed and has a dated next step, with nothing overdue or due today.':'Choose another stage or start a new enquiry.'}</p>{layout==='Needs attention'&&<button className="crm-secondary" onClick={()=>{setLayout('All enquiries');setStageFilter('Open');}}>View all enquiries</button>}</div>}</div>}
 {!inspectorOpen&&message&&<div className="pipeline-feedback" role="status">{message}{undo&&<button disabled={busy} onClick={undoMove}>Undo</button>}<button aria-label="Dismiss update" onClick={()=>{setMessage('');setUndo(null);}}><X size={15}/></button></div>}
 <Dialog.Root open={inspectorOpen} onOpenChange={open=>{if(busy)return;setInspectorOpen(open);if(!open)onSelectOpportunity?.(null);}}><Dialog.Portal><Dialog.Overlay className="crm-inspector-overlay"/><Dialog.Content className="crm-inspector crm-inspector-drawer pipeline-drawer" aria-describedby={undefined} onCloseAutoFocus={e=>{e.preventDefault();if(openerRef.current?.isConnected)openerRef.current.focus();else headingRef.current?.focus();}}><div className="pl-dhead"><div className="pl-drow"><div><Dialog.Title>{detail?.clientName|| (detailError?'Enquiry unavailable':'Opening enquiry…')}</Dialog.Title>{detail&&<p className="pl-dsub">{[detail.title,signals[detail.id]?.eventDate&&shortDate(signals[detail.id].eventDate),signals[detail.id]?.venue].filter(Boolean).join(' · ')}</p>}</div><Dialog.Close asChild><button type="button" className="pl-close" aria-label="Close enquiry" disabled={busy}><X size={18}/></button></Dialog.Close></div>
 {detail&&<><div className="pl-path" role="group" aria-label="Enquiry stage">{[...activeStages,'Won'].map((stage,index,list)=>{const at=list.indexOf(detail.stage);return <button type="button" key={stage} className={index<at?'is-done':index===at?'is-now':''} aria-pressed={index===at} disabled={busy||editing} onClick={()=>move(detail,stage)}>{labels[stage]}</button>;})}</div>
 <div className="pl-dmeta">{detail.stage==='Lost'?<Chip tone="bad">{labels.Lost}{detail.lostReason?': '+detail.lostReason:''}</Chip>:<button type="button" className="pipeline-quiet" disabled={busy||editing} onClick={()=>move(detail,'Lost')}>{labels.Lost}</button>}<button type="button" className="pipeline-quiet" onClick={()=>{setDraft(defaultDraft(detail));setEditing(v=>!v);setActionError('');}}><Pencil size={14}/>{editing?'Close editor':'Edit details'}</button></div>
 {!editing&&<div className="pl-dtabs" role="tablist" aria-label="Enquiry sections">{[['overview','Overview'],['quote',labels.Proposal==='Preparing quote'?'Quote':'Proposal'],['follow','Follow-ups'],['timeline','Timeline']].map(([value,label])=><button type="button" role="tab" key={value} aria-selected={drawerTab===value} onClick={()=>setDrawerTab(value)}>{label}</button>)}</div>}</>}</div>{detail?<div className="pl-dbody">
 {actionError&&<p className="crm-alert" role="alert">{actionError}</p>}{message&&<div className="pipeline-drawer-feedback" role="status">{message}{undo&&<button disabled={busy} onClick={undoMove}>Undo</button>}</div>}
 <div hidden={editing||drawerTab!=='overview'}><DealOverview detail={detail} signal={signals[detail.id]} studio={studio} request={request} run={run} busy={busy} openProject={openProject} onChanged={dealChanged} onTab={setDrawerTab}/><dl className="pl-kv"><dt>Next step</dt><dd>{nextStepFor(detail,detail.tasks||[])?.title||'Set a next step'}</dd><dt>Last client message</dt><dd>{signals[detail.id]?.lastClientMessageAt?shortDate(signals[detail.id].lastClientMessageAt):'None yet'}</dd><dt>Expected decision</dt><dd>{detail.expectedClose?shortDate(detail.expectedClose):'Not set'}</dd></dl><section className="pipeline-intake"><header><h3>Their request</h3><span className="pipeline-review-state">{detail.reviewedAt?'Reviewed':detail.needsReview?'Needs review':'Not reviewed'}</span></header>{detail.intake?<EnquiryRequest intake={detail.intake} studio={studio}/>:<><p className="pipeline-received">{detail.source||'Direct enquiry'} · {shortDate(detail.receivedAt||detail.createdAt)}</p><p className="pipeline-request-idea">{detail.description||'No request details yet. Add a brief note in Edit details.'}</p></>}
 <div className="pipeline-review-actions"><button className={detail.reviewedAt?'pipeline-quiet':'crm-primary'} disabled={busy} onClick={reviewEnquiry}>{detail.reviewedAt?'Mark for review':'Mark reviewed'}</button>{detail.projectId&&<button className="pipeline-quiet" onClick={()=>openProject({id:detail.projectId},'Conversation')}><MessageSquare size={14}/>Open conversation</button>}</div>{detail.reviewedAt&&<p className="pipeline-reviewed-by">Reviewed by {detail.reviewedBy} · {shortDate(detail.reviewedAt)}</p>}</section><section className="pipeline-next-section"><header><h3>Next steps</h3><span>Private to your studio</span></header>{(detail.tasks||[]).filter(t=>!t.completed).map(t=><div className="pipeline-task" key={t.id}><button className="pipeline-task-check" disabled={busy} onClick={()=>toggleTask(t)} aria-label={'Complete '+t.title}><Check size={14}/></button><div><strong>{t.title}</strong><small className={t.dueDate&&t.dueDate<today?'is-overdue':''}>{t.dueDate?shortDate(t.dueDate):'Choose a date'} · {taskOwner(t)}</small></div>{openTask&&<button className="pipeline-quiet" onClick={()=>openTask(t.id)}>Edit</button>}</div>)}{!(detail.tasks||[]).some(t=>!t.completed)&&<p className="pipeline-muted">{isOpenEnquiry(detail)?'What should happen next? Add an action and a date.':'No open next steps.'}</p>}
 <form className="pipeline-next-form" onSubmit={addTask}><label className="sr-only" htmlFor="pipeline-next-title">Next step</label><input id="pipeline-next-title" ref={taskInput} required maxLength="200" placeholder="Add a next step…" value={taskTitle} onChange={e=>setTaskTitle(e.target.value)}/><div><label>Follow-up date<input aria-label="Follow-up date" type="date" required value={taskDate} onChange={e=>setTaskDate(e.target.value)}/></label><button className="crm-primary" disabled={busy||!taskTitle.trim()||!taskDate}><Plus size={14}/>Add step</button></div></form>
 {isOpenEnquiry(detail)&&<div className="pipeline-suggestions"><button onClick={()=>suggestTask('Arrange a consultation with '+detail.clientName)}><CalendarDays size={13}/>Consultation</button><button onClick={()=>suggestTask('Follow up with '+detail.clientName)}><Clock size={13}/>Follow-up</button>{detail.projectId&&<button onClick={()=>openProject({id:detail.projectId},labels.Proposal==='Preparing quote'?'Estimate':'Proposal')}><FileText size={13}/>{labels.Proposal==='Preparing quote'?'Prepare quote':'Prepare proposal'}</button>}</div>}
 {(detail.tasks||[]).some(t=>t.completed)&&<details className="pipeline-completed"><summary>{detail.tasks.filter(t=>t.completed).length} completed steps</summary>{detail.tasks.filter(t=>t.completed).map(t=><button disabled={busy} key={t.id} onClick={()=>toggleTask(t)} aria-label={'Reopen '+t.title}><Check size={13}/>{t.title}</button>)}</details>}</section>
 <section className="pipeline-context"><h3>{detail.projectStatus==='Enquiry'?'Enquiry project':'Project & client'}</h3><p>{detail.projectStatus==='Enquiry'?'The submitted brief has a project space. Start planning when you are ready to take the work forward.':detail.projectId?'Project stage: '+detail.projectStatus:'Create a project when the enquiry is ready for delivery.'}</p>{detail.description&&detail.intake&&<p>{detail.description}</p>}<dl className="pipeline-request-facts"><div><dt>Expected decision</dt><dd>{detail.expectedClose?shortDate(detail.expectedClose):'Not set'}</dd></div>{detail.projectDate&&<div><dt>{workflowFor(studio,{brief:detail.intake?.brief}).date}</dt><dd>{shortDate(detail.projectDate)}</dd></div>}</dl><div>{detail.projectId?<button className="crm-secondary" onClick={()=>openProject({id:detail.projectId},'Brief')}><FileText size={15}/>Open project brief</button>:<button className="crm-secondary" onClick={()=>{setActionError('');setCreatingProject(true);}}><Plus size={15}/>Create linked project</button>}<button className="pipeline-quiet" onClick={()=>openClient(detail.clientId)}>Client record</button></div>{detail.projectStatus==='Enquiry'&&<button className="pipeline-begin-planning crm-primary" disabled={busy||!detail.reviewedAt} onClick={beginPlanning}>Start planning</button>}<small>{detail.projectStatus==='Enquiry'&&!detail.reviewedAt?'Review the request before starting planning. ':''}Planning does not confirm a booking. Enquiry confirmation, design approvals, contracts and payments have separate records.</small></section></div>
 <div hidden={editing||drawerTab!=='quote'}>{drawerTab==='quote'&&<DealQuote detail={detail} signal={signals[detail.id]} studio={studio} request={request} run={run} busy={busy} openProject={openProject} onChanged={dealChanged} planTemplate={pipeline?.planTemplate}/>}</div>
 <div hidden={editing||drawerTab!=='follow'}><DealFollowUps detail={detail} signal={signals[detail.id]} settings={pipeline?.settings} studio={studio} request={request} run={run} busy={busy} onChanged={dealChanged} onOpenAutomations={()=>{setInspectorOpen(false);onSelectOpportunity?.(null);setLayout('Automations');}}/>
  {detail.stage!=='Won'&&detail.stage!=='Lost'&&<QuietHelper className="pl-quiet-helper" studio={studio} request={request} kind="follow-up" target={{opportunityId:detail.id}} useLabel="Send in project space" onUse={detail.projectId&&signals[detail.id]?.portalClient?async text=>{await request(`/api/projects/${detail.projectId}/messages?studio=${studio.id}`,'POST',{text});await dealChanged?.();}:undefined}/>}</div>
 <div hidden={editing||drawerTab!=='timeline'}><section className="pipeline-history"><p className="pl-muted">Quotes, proposals, holds, payments and stage moves are recorded for you. Add calls and notes by hand.</p> <header><h3>Recent activity</h3><button className="pipeline-quiet" onClick={()=>setLogging(v=>!v)}><Plus size={14}/>{logging?'Close':'Log update'}</button></header>{logging&&<form className="crm-inline-form" onSubmit={addActivity}><WorkspaceSelect label="Activity type" value={activityKind} onValueChange={setActivityKind} options={['Call','Meeting','Email','Note']}/><input name="title" required maxLength="160" placeholder="What happened?" aria-label="Activity title"/><textarea name="detail" rows="2" maxLength="3000" placeholder="Details worth remembering" aria-label="Activity details"/><button className="crm-primary" disabled={busy}>Save update</button></form>}
 <ol className="pipeline-timeline">{(detail.activities||[]).map(a=><li key={a.id}><i/><div><strong>{a.kind==='System'&&a.title.startsWith('Moved from ')?a.title.replace(/Discovery|Qualified|Proposal|Negotiation|Won|Lost/g,s=>labels[s]):a.title}</strong>{a.detail&&<p>{a.detail}</p>}<small>{a.by==='Caleane automation'?'Caleane':a.by} · {shortDate(a.at)}{a.by==='Caleane automation'&&<span className="pl-auto">Auto</span>}</small></div></li>)}</ol>{!detail.activities?.length&&<p className="pipeline-muted">Calls, meetings and updates will appear here.</p>}</section></div>
 {editing&&<form className="crm-editor pipeline-editor" onSubmit={save}><h3>Edit enquiry</h3><label>Enquiry title<input value={draft.title} maxLength="200" required onChange={e=>setDraft({...draft,title:e.target.value})}/></label><label>Stage<WorkspaceSelect label="Edit enquiry stage" value={draft.stage} onValueChange={stage=>setDraft({...draft,stage})} options={stageOptions}/></label><div className="crm-form-pair"><label>Estimated value<input type="number" min="0" step="0.01" value={draft.amount} onChange={e=>setDraft({...draft,amount:e.target.value})}/></label><label>Currency<WorkspaceSelect label="Currency" value={draft.currency} onValueChange={currency=>setDraft({...draft,currency})} options={['GBP','EUR','USD']}/></label></div><label>Expected decision date<input type="date" value={draft.expectedClose} onChange={e=>setDraft({...draft,expectedClose:e.target.value})}/></label><p className="pipeline-muted">When you expect their decision. The project date stays in the brief.</p>{draft.stage==='Lost'&&<label>Reason not proceeding<input required maxLength="500" value={draft.lostReason} onChange={e=>setDraft({...draft,lostReason:e.target.value})} placeholder="What changed?"/></label>}<label>Source<input maxLength="120" value={draft.source} onChange={e=>setDraft({...draft,source:e.target.value})}/></label><label>Brief note<textarea rows="3" maxLength="3000" value={draft.description} onChange={e=>setDraft({...draft,description:e.target.value})}/></label><details><summary>Forecast settings</summary><label>Probability %<input type="number" min="0" max="100" step="1" value={draft.probability} onChange={e=>setDraft({...draft,probability:e.target.value})}/></label></details><button className="crm-primary" disabled={busy}>Save enquiry</button></form>}
 </div>:<p className={detailError?'crm-drawer-error':'crm-drawer-loading'} role={detailError?'alert':undefined}>{detailError||'Loading the enquiry and next steps…'}</p>}</Dialog.Content></Dialog.Portal></Dialog.Root>
 <Dialog.Root open={!!closingEnquiry} onOpenChange={v=>{if(!v&&!busy)setClosingEnquiry(null);}}><Dialog.Portal><Dialog.Overlay className="modal-backdrop"/><Dialog.Content className="modal crm-create-dialog pipeline-create"><Dialog.Close asChild><button className="close" aria-label="Close decision"><X size={18}/></button></Dialog.Close><Dialog.Title>Not proceeding</Dialog.Title><Dialog.Description>Record what changed for {closingEnquiry?.clientName}. Their client record and project remain available.</Dialog.Description>{actionError&&<p role="alert">{actionError}</p>}<form onSubmit={async e=>{e.preventDefault();const reason=new FormData(e.currentTarget).get('reason');const previous=closingEnquiry;const result=await act('/api/opportunities/'+previous.id+q,'PATCH',{revision:previous.revision,stage:'Lost',lostReason:reason});if(result){stageChanged(previous,result.opportunity);if(selected===previous.id){setDetail(result.opportunity);setDraft(defaultDraft(result.opportunity));}setClosingEnquiry(null);await reload();}}}><label>Reason<input name="reason" required maxLength="500" placeholder="e.g. Dates changed or budget did not fit"/></label><button className="crm-primary" disabled={busy}>Mark as not proceeding</button></form></Dialog.Content></Dialog.Portal></Dialog.Root>
 <Dialog.Root open={creating} onOpenChange={v=>{if(!busy)setCreating(v);}}><Dialog.Portal><Dialog.Overlay className="modal-backdrop"/><Dialog.Content className="modal crm-create-dialog pipeline-create"><Dialog.Close asChild><button className="close" aria-label="Close new enquiry"><X size={18}/></button></Dialog.Close><Dialog.Title>New enquiry</Dialog.Title><Dialog.Description>Start with a client and the idea. Add the finer details later.</Dialog.Description>{actionError&&<p role="alert">{actionError}</p>}<form onSubmit={create}><label>Client<WorkspaceSelect name="clientId" label="Client" required defaultValue={initialClientId||undefined} placeholder="Choose a client" options={clients.map(c=>({value:c.id,label:c.name}))}/></label><label>Enquiry<input name="title" maxLength="200" required placeholder="e.g. Spring launch installation"/></label><label>Brief note<textarea name="description" rows="3" maxLength="3000" placeholder="What do they have in mind?"/></label><details><summary>Add value, source or stage</summary><label>Source<input name="source" maxLength="120" placeholder="Referral, website, returning client…"/></label><div className="crm-form-pair"><label>Estimated value<input name="amount" type="number" min="0" step="0.01" placeholder="Not estimated"/></label><label>Currency<WorkspaceSelect name="currency" label="Currency" defaultValue="GBP" options={['GBP','EUR','USD']}/></label></div><label>Stage<WorkspaceSelect name="stage" label="Starting stage" defaultValue="Discovery" options={stageOptions.filter(o=>activeStages.includes(o.value))}/></label><label>Expected decision date<input name="expectedClose" type="date"/></label></details><button className="crm-primary" disabled={busy}>Create enquiry</button></form></Dialog.Content></Dialog.Portal></Dialog.Root>
 <Dialog.Root open={creatingProject} onOpenChange={v=>{if(!busy)setCreatingProject(v);}}><Dialog.Portal><Dialog.Overlay className="modal-backdrop"/><Dialog.Content className="modal crm-create-dialog pipeline-create"><Dialog.Close asChild><button className="close" aria-label="Close new project"><X size={18}/></button></Dialog.Close><Dialog.Title>Begin the project</Dialog.Title><Dialog.Description>Keep this enquiry and {detail?.clientName} connected to the delivery space.</Dialog.Description>{actionError&&<p role="alert">{actionError}</p>}<form onSubmit={createProject}><label>Service area<WorkspaceSelect name="workflowType" label="Service area" defaultValue={studio.branding?.profession||DEFAULT_WORKFLOW} options={workflowOptionsFor(studio.branding?.profession).map(o=>({value:o.id,label:o.label}))}/></label><label>Project type<input name="occasion" maxLength="120" defaultValue={detail?.title||''} required/></label><label>Project date<input name="date" type="date"/></label><label>Location / delivery<input name="venue" maxLength="300" placeholder="To be decided"/></label><label>Starting idea<textarea name="vision" rows="4" maxLength="5000" defaultValue={detail?.description||''}/></label><button className="crm-primary" disabled={busy}>Create linked project</button></form></Dialog.Content></Dialog.Portal></Dialog.Root>
 </section>;
}

const answerText=value=>Array.isArray(value)?value.join(', '):typeof value==='boolean'?(value?'Yes':'No'):String(value??'');
function EnquiryRequest({intake,studio}){
 const brief=intake.brief||{},workflow=workflowFor(studio,{brief});
 const facts=[['Service',brief.occasion],[workflow.date,brief.date?shortDate(brief.date):'To be decided'],[workflow.place,brief.venue||'To discuss'],['Client budget',brief.budget||'Not provided']];
 const answers=[['Name',brief.name],['Email',brief.email],['Colour direction',[...(brief.colours||[]),brief.customColours].filter(Boolean).join(', ')],['Inspiration',brief.pinterest],...briefFieldsFor(workflow.id).map(f=>[f.label,brief.details?.[f.key]]),...(brief.intakeAnswers||[]).filter(a=>a.applicable!==false).map(a=>[a.label,answerText(a.value)]),...(intake.consentText?[[intake.consentText,intake.consent?'Confirmed':'Not confirmed']]:[])].filter(([,value])=>value!==undefined&&value!==null&&value!=='');
 return <><p className="pipeline-received">{intake.formName?'Received through '+intake.formName:'Project brief'} · {shortDate(intake.submittedAt)}{intake.version?' · Form v'+intake.version:''}</p><p className="pipeline-request-idea">{brief.vision||'No starting idea provided.'}</p><dl className="pipeline-request-facts">{facts.map(([label,value])=><div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl><details className="pipeline-original"><summary>{intake.original?'View original submission':'View brief details'}</summary><p>{intake.original?'These are the answers as submitted. Later changes are recorded in the project brief.':'This enquiry predates saved form responses. These are the current project brief details.'}</p><dl>{answers.map(([label,value],i)=><div key={i}><dt>{label}</dt><dd>{answerText(value)}</dd></div>)}</dl></details></>;
}

export function CRMTasks({studio,request,run,busy,openClient,openOpportunity,taskId}){
 const [tasks,setTasks]=useState([]),[clients,setClients]=useState([]),[opportunities,setOpportunities]=useState([]),[filter,setFilter]=useState('Open'),[search,setSearch]=useState(''),[creating,setCreating]=useState(false),[editing,setEditing]=useState(null),[taskClientId,setTaskClientId]=useState(''),[error,setError]=useState('');const q='?studio='+studio.id;
 async function reload(){try{const [t,c,o]=await Promise.all([request('/api/crm/tasks'+q),request('/api/clients'+q),request('/api/opportunities'+q)]);setTasks(t.tasks);setClients(c.clients);setOpportunities(o.opportunities);setError('');}catch(e){setError(readError(e));}}
 useEffect(()=>{reload();},[studio.id]);
 useEffect(()=>{if(!taskId||!tasks.some(task=>task.id===taskId))return;setFilter('All');setSearch('');requestAnimationFrame(()=>document.getElementById('crm-task-'+taskId)?.scrollIntoView({block:'center',behavior:'smooth'}));},[taskId,tasks]);
 const today=localISODate();
 const visible=tasks.filter(t=>(filter==='All'||filter==='Open'&&!t.completed||filter==='Overdue'&&!t.completed&&t.dueDate&&t.dueDate<today||filter==='Done'&&t.completed)&&(t.title+' '+t.clientName+' '+(t.opportunityTitle||'')).toLowerCase().includes(search.toLowerCase()));
 async function toggle(t){const d=await run(()=>request('/api/crm/tasks/'+t.id+q,'PATCH',{completed:!t.completed}));if(d)await reload();}
 async function create(e){e.preventDefault();const form=e.currentTarget,data=Object.fromEntries(new FormData(form));const d=await run(()=>request('/api/crm/tasks'+q,'POST',data));if(d){setCreating(false);await reload();}}
 async function saveTask(e){e.preventDefault();if(!editing)return;const data=Object.fromEntries(new FormData(e.currentTarget));const d=await run(()=>request('/api/crm/tasks/'+editing.id+q,'PATCH',data));if(d){setEditing(null);await reload();}}
 return <section className="crm-screen crm-tasks-screen"><header className="crm-page-heading workspace-page-heading"><div><p className="crm-overline">STUDIO / FOLLOW THROUGH</p><h1>Keep the next step clear.</h1><p>Every action has a person and a place in the relationship.</p></div><button className="crm-primary" onClick={()=>setCreating(true)}><Plus size={16}/>New task</button></header>{error&&<p className="crm-alert" role="alert">{error}</p>}<div className="crm-stat-strip three"><div><span>Open</span><strong>{tasks.filter(t=>!t.completed).length.toString().padStart(2,'0')}</strong></div><div><span>Overdue</span><strong>{tasks.filter(t=>!t.completed&&t.dueDate&&t.dueDate<today).length.toString().padStart(2,'0')}</strong></div><div><span>Completed</span><strong>{tasks.filter(t=>t.completed).length.toString().padStart(2,'0')}</strong></div></div><div className="crm-toolbar"><div className="crm-segmented" role="group" aria-label="Task filter">{['Open','Overdue','Done','All'].map(x=><button key={x} aria-pressed={filter===x} onClick={()=>setFilter(x)}>{x}</button>)}</div><label className="crm-search"><Search size={16}/><input aria-label="Search tasks" placeholder="Find a task or client" value={search} onChange={e=>setSearch(e.target.value)}/></label></div><div className="crm-task-list">{visible.map(t=><article key={t.id} id={'crm-task-'+t.id} className={(t.completed?'done ':'')+(taskId===t.id?'is-search-result':'')}><button className="crm-task-complete" onClick={()=>toggle(t)} aria-label={t.completed?'Reopen '+t.title:'Complete '+t.title}>{t.completed&&<Check size={15}/>}</button><div><div className="crm-task-title-row"><strong>{t.title}</strong><button onClick={()=>setEditing(t)} aria-label={"Edit "+t.title}><Pencil size={15}/></button></div>{t.detail&&<p>{t.detail}</p>}<small><button onClick={()=>openClient(t.clientId)}>{t.clientName}</button>{t.opportunityId&&<> · <button onClick={()=>openOpportunity(t.opportunityId)}>{t.opportunityTitle}</button></>}</small></div><span className={'crm-priority '+t.priority.toLowerCase()}>{t.priority}</span><time className={t.dueDate<today&&!t.completed?'overdue':''}>{t.dueDate?shortDate(t.dueDate):'No due date'}</time></article>)}{!visible.length&&<div className="crm-empty">No tasks in this view. Add a next step to keep a relationship moving.</div>}</div>
 <Dialog.Root open={!!editing} onOpenChange={open=>{if(!open)setEditing(null);}}><Dialog.Portal><Dialog.Overlay className="modal-backdrop"/><Dialog.Content className="modal crm-create-dialog"><Dialog.Close asChild><button className="close" aria-label="Close"><X size={18}/></button></Dialog.Close><Dialog.Title>Edit next step</Dialog.Title><Dialog.Description>Keep the owner’s action and timing up to date.</Dialog.Description>{editing&&<form key={editing.id} onSubmit={saveTask}><p className="crm-edit-context">{editing.clientName}{editing.opportunityTitle?' · '+editing.opportunityTitle:''}</p><label>Task<input name="title" required maxLength="200" defaultValue={editing.title}/></label><label>Details<textarea name="detail" rows="3" maxLength="2000" defaultValue={editing.detail}/></label><div className="crm-form-pair"><label>Due date<input name="dueDate" type="date" defaultValue={editing.dueDate}/></label><label>Priority<select name="priority" defaultValue={editing.priority}><option>Normal</option><option>High</option><option>Low</option></select></label></div><button className="crm-primary" disabled={busy}>Save task</button></form>}</Dialog.Content></Dialog.Portal></Dialog.Root>
 <Dialog.Root open={creating} onOpenChange={setCreating}><Dialog.Portal><Dialog.Overlay className="modal-backdrop"/><Dialog.Content className="modal crm-create-dialog"><Dialog.Close asChild><button className="close" aria-label="Close"><X size={18}/></button></Dialog.Close><Dialog.Title>New CRM task</Dialog.Title><Dialog.Description>Give this action a person, due date and priority.</Dialog.Description><form onSubmit={create}><label>Client<select name="clientId" required value={taskClientId} onChange={e=>setTaskClientId(e.target.value)}><option value="" disabled>Choose a client</option>{clients.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Opportunity <small>(optional)</small><select name="opportunityId" key={taskClientId}><option value="">General relationship task</option>{opportunities.filter(o=>o.clientId===taskClientId).map(o=><option key={o.id} value={o.id}>{o.title}</option>)}</select></label><label>Task<input name="title" required maxLength="200" placeholder="What needs to happen?"/></label><label>Details<textarea name="detail" rows="3" maxLength="2000"/></label><div className="crm-form-pair"><label>Due date<input name="dueDate" type="date"/></label><label>Priority<select name="priority"><option>Normal</option><option>High</option><option>Low</option></select></label></div><button className="crm-primary" disabled={busy}>Create task</button></form></Dialog.Content></Dialog.Portal></Dialog.Root></section>;
}

export function ClientCRMPanel({studio,client,projects,openProject,request,run,busy,kind,openOpportunity}){
 const [opportunities,setOpportunities]=useState([]),[activities,setActivities]=useState([]),[loading,setLoading]=useState(true),[error,setError]=useState('');const q='?studio='+studio.id;
 async function reload(){try{const [o,a]=await Promise.all([request('/api/opportunities'+q),request('/api/clients/'+client.id+'/activities'+q)]);setOpportunities(o.opportunities.filter(x=>x.clientId===client.id));setActivities(a.activities);setError('');}catch(e){setError(readError(e));}finally{setLoading(false);}}
 useEffect(()=>{setLoading(true);reload();},[studio.id,client.id]);
 async function log(e){e.preventDefault();const form=e.currentTarget,data=Object.fromEntries(new FormData(form));const d=await run(()=>request('/api/clients/'+client.id+'/activities'+q,'POST',data));if(d){form.reset();await reload();}}
 const projectActivities=projects.flatMap(p=>p.activity.map(a=>({id:'project-'+a.id,kind:'Project',title:a.text,detail:p.title,by:a.actor,at:a.at,project:p})));
 const history=[...activities,...projectActivities].sort((a,b)=>b.at.localeCompare(a.at));
 if(loading)return <div className="folio-overview crm-client-panel">Opening relationship history…</div>;
 return <section className="folio-overview crm-client-panel"><div className="crm-section-title"><h2>{kind==='Opportunities'?'Opportunities':'Activity history'}</h2><span>{kind==='Opportunities'?opportunities.length:history.length}</span></div>{error&&<p className="crm-alert" role="alert">{error}</p>}{kind==='Opportunities'?<><p>Every possible project and its path from first idea to agreement.</p><button className="crm-secondary" onClick={()=>openOpportunity(null,client.id)}><Plus size={15}/>New opportunity</button><div className="crm-client-deals">{opportunities.map(o=><button key={o.id} onClick={()=>openOpportunity(o.id,client.id)}><span><strong>{o.title}</strong><small>{o.stage} · {o.source||'Direct relationship'}</small></span><span>{o.amountMinor?money(o.amountMinor,o.currency):'To discuss'}</span></button>)}{!opportunities.length&&<p>No opportunities yet. Open one before the project begins.</p>}</div></>:<><form className="crm-client-activity-form" onSubmit={log}><div><select name="kind" aria-label="Activity type"><option>Call</option><option>Meeting</option><option>Email</option><option>Note</option></select><input name="title" maxLength="160" required placeholder="What happened?" aria-label="Activity title"/></div><textarea name="detail" rows="3" maxLength="3000" placeholder="Details worth remembering" aria-label="Activity details"/><button className="crm-secondary" disabled={busy}>Log activity</button></form><div className="crm-timeline">{history.map(a=><article key={a.id}><span className="crm-timeline-dot"/><div><small>{a.kind} · {shortDate(a.at)} · {a.by}</small><strong>{a.title}</strong>{a.detail&&<p>{a.detail}</p>}{a.opportunityId&&<button onClick={()=>openOpportunity(a.opportunityId,client.id)}>Open opportunity</button>}{a.project&&<button onClick={()=>openProject(a.project,'Activity')}>Open project</button>}</div></article>)}{!history.length&&<p>No activity logged yet. Calls, meetings and notes stay with the client record.</p>}</div></>}</section>;
}
